const CACHE_VERSION = 'v3';
const CACHE_NAME = `pybash-${CACHE_VERSION}`;
const PRECACHE_ASSETS = [
  '/',
  '/index.html',
  '/styles.css',
  '/app.js',
  '/offline.html',
  '/icons/icon-192.png'
];

self.addEventListener('install', (event) => {
  console.log('[SW] Installing', CACHE_NAME);
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      // addAll falla completo si UN solo recurso da 404.
      // Para recursos críticos usamos add individual controlado.
      const critical = ['/', '/index.html', '/styles.css', '/app.js'];
      const optional = ['/offline.html', '/icons/icon-192.png'];

      await cache.addAll(critical);
      await Promise.allSettled(
        optional.map(url => cache.add(url).catch(e => console.warn('[SW] Opcional falló:', url)))
      );
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Limpieza de caches viejos: evita que el storage crezca sin límite
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter(key => key.startsWith('pybash-') && key !== CACHE_NAME)
          .map(key => caches.delete(key))
      );
      await self.clients.claim();
    })()
  );
});

