const CACHE_STATIC = 'pybash-static-v3';
const CACHE_RUNTIME = 'pybash-runtime-v3';

// Estrategia 1: Cache First para assets versionados
const cacheFirst = async (request) => {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(CACHE_RUNTIME);
    cache.put(request, response.clone());
  }
  return response;
};

// Estrategia 2: Network First para datos de API
const networkFirst = async (request, timeoutMs = 3000) => {
  try {
    const timeout = new Promise((_, reject) =>
      setTimeout(() => reject(new Error('timeout')), timeoutMs)
    );
    const response = await Promise.race([fetch(request), timeout]);
    if (response.ok) {
      const cache = await caches.open(CACHE_RUNTIME);
      cache.put(request, response.clone());
    }
    return response;
  } catch (err) {
    const cached = await caches.match(request);
    return cached || new Response(
      JSON.stringify({ error: 'offline', data: null }),
      { headers: { 'Content-Type': 'application/json' } }
    );
  }
};

// Estrategia 3: Stale While Revalidate para navegación HTML
const staleWhileRevalidate = async (request) => {
  const cache = await caches.open(CACHE_STATIC);
  const cached = await cache.match(request);
  const networkPromise = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => cached || cache.match('/offline.html'));
  return cached || networkPromise;
};

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return; // Solo cachear GET
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // No cachear terceros

  if (request.mode === 'navigate') {
    event.respondWith(staleWhileRevalidate(request));
  } else if (url.pathname.startsWith('/api/')) {
    event.respondWith(networkFirst(request));
  } else {
    event.respondWith(cacheFirst(request));
  }
});

