const OFFLINE_URL = '/offline.html';
const CACHE_STATIC = 'pybash-static-v3';

// Precachear la página offline durante install para garantizar que exista
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_STATIC).then((cache) =>
      cache.addAll(['/', '/index.html', '/styles.css', '/app.js', OFFLINE_URL])
    )
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  // No interceptar cross-origin (analytics, fuentes, APIs externas)
  if (url.origin !== self.location.origin) return;

  // NAVEGACIÓN: red primero, fallback a cache, fallback a página offline
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const networkResponse = await fetch(request);
          const cache = await caches.open(CACHE_STATIC);
          cache.put(request, networkResponse.clone());
          return networkResponse;
        } catch (networkError) {
          // Sin red: buscar la ruta exacta en cache
          const cachedPage = await caches.match(request);
          if (cachedPage) return cachedPage;
          // Ni la ruta exacta: servir la página offline genérica
          const offlinePage = await caches.match(OFFLINE_URL);
          return offlinePage || new Response(
            '<h1>Sin conexión</h1><p>No pudimos cargar esta página.</p>',
            { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } }
          );
        }
      })()
    );
    return;
  }

  // RECURSOS ESTÁTICOS: cache primero con actualización en segundo plano
  event.respondWith(
    (async () => {
      const cached = await caches.match(request);
      const fetchPromise = fetch(request)
        .then((networkResponse) => {
          if (networkResponse.ok) {
            const cacheCopy = networkResponse.clone();
            caches.open(CACHE_STATIC).then((c) => c.put(request, cacheCopy));
          }
          return networkResponse;
        })
        .catch(() => cached);
      return cached || fetchPromise;
    })()
  );
});

