const CACHE_VERSION = '__BUILD_VERSION__'; // ej. git hash o timestamp
const CACHE_NAME = `pybash-${CACHE_VERSION}`;
const PRECACHE = ['/', '/index.html', '/app.js', '/styles.css', '/offline.html'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      await cache.addAll(PRECACHE);
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys.filter(k => k.startsWith('pybash-') && k !== CACHE_VERSION && k !== CACHE_NAME)
            .map(k => caches.delete(k))
      );
      await self.clients.claim();
      // Notificar a todas las pestañas abiertas que hay un nuevo SW activo
      const clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach(client => client.postMessage({ type: 'SW_UPDATED', version: CACHE_VERSION }));
    })()
  );
});

