// NO usar skipWaiting ciego: avisar al usuario y dejarle decidir
async function setupUpdatePrompt() {
  const reg = await navigator.serviceWorker.getRegistration();
  if (!reg) return;

  if (reg.waiting) {
    showUpdateBanner(); // Ya hay una actualización esperando
  }

  reg.addEventListener('updatefound', () => {
    const newWorker = reg.installing;
    newWorker.addEventListener('statechange', () => {
      if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
        showUpdateBanner();
      }
    });
  });
}

function showUpdateBanner() {
  const banner = document.createElement('div');
  banner.className = 'update-banner';
  banner.innerHTML = `
    <p>Nueva versión disponible</p>
    <button type="button" id="reload-btn">Actualizar</button>
  `;
  document.body.appendChild(banner);
  document.getElementById('reload-btn').addEventListener('click', () => {
    navigator.serviceWorker.ready.then((reg) => {
      reg.waiting?.postMessage({ type: 'SKIP_WAITING' });
    });
  });
}

// Recargar la página cuando el nuevo SW tome el control
let refreshing = false;
navigator.serviceWorker.addEventListener('controllerchange', () => {
  if (refreshing) return;
  refreshing = true;
  window.location.reload();
});

