const VERSION = 'v1';
const CACHE_STATIC = `pybash-static-${VERSION}`;
const CACHE_RUNTIME = `pybash-runtime-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_STATIC).then((cache) =>
      cache.addAll(['/', '/index.html', '/styles.css', '/app.js', '/offline.html'])
    )
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys.filter(k => k.startsWith('pybash-') && !k.includes(VERSION))
            .map(k => caches.delete(k))
      )
    ).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // FILTRO 1: solo GET
  if (request.method !== 'GET') return;
  // FILTRO 2: solo mismo origen
  if (url.origin !== self.location.origin) return;

  // Navegación: Network First con fallback
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then(res => {
          if (res.ok) {
            const copy = res.clone();
            caches.open(CACHE_STATIC).then(c => c.put(request, copy));
          }
          return res;
        })
        .catch(() => caches.match(request).then(r => r || caches.match('/offline.html')))
    );
    return;
  }

  // Assets: Cache First, pero solo si la respuesta es válida
  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request).then((res) => {
        if (res.ok) {  // FILTRO 3: no cachear errores
          const copy = res.clone();  // FILTRO 4: clonar antes de consumir
          caches.open(CACHE_RUNTIME).then(c => c.put(request, copy));
        }
        return res;
      });
    })
  );
});

