// ============ SERVICE WORKER AUDITADO Y ENDURECIDO ============
const BUILD_ID = '20260929-a'; // Cambiar en cada deploy
const CACHES = {
  static: `pybash-s-${BUILD_ID}`,
  runtime: `pybash-r-${BUILD_ID}`,
  dataset: `pybash-data-${BUILD_ID}` // Cache separado para tus chunks JSON
};
const MAX_RUNTIME_ENTRIES = 60; // Límite de crecimiento de cache

const PRECACHE = ['/', '/index.html', '/styles.css', '/app.js', '/offline.html'];
const DATASET_FILES = ['/data/chunks-f0.json']; // Tu dataset, cacheado aparte

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const [staticCache, dataCache] = await Promise.all([
        caches.open(CACHES.static),
        caches.open(CACHES.dataset)
      ]);
      await staticCache.addAll(PRECACHE);
      // El dataset es crítico: si falla, la app no tiene contenido
      await dataCache.addAll(DATASET_FILES);
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const validNames = Object.values(CACHES);
      const keys = await caches.keys();
      await Promise.all(
        keys.filter(k => k.startsWith('pybash-') && !validNames.includes(k))
            .map(k => caches.delete(k))
      );
      await self.clients.claim();
    })()
  );
});

// Límite de tamaño: evita que el storage crezca infinitamente
const trimCache = async (cacheName, maxItems) => {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length > maxItems) {
    await cache.delete(keys[0]);
    return trimCache(cacheName, maxItems);
  }
};

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // DATASET: Stale While Revalidate (contenido de estudio siempre disponible)
  if (url.pathname.startsWith('/data/')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHES.dataset);
        const cached = await cache.match(request);
        const revalidate = fetch(request)
          .then(res => {
            if (res.ok) cache.put(request, res.clone());
            return res;
          })
          .catch(() => cached);
        return cached || revalidate;
      })()
    );
    return;
  }

  // NAVEGACIÓN: Network First + fallback offline
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const res = await fetch(request);
          if (res.ok) {
            const cache = await caches.open(CACHES.static);
            cache.put(request, res.clone());
          }
          return res;
        } catch {
          return await caches.match(request)
              || await caches.match('/index.html')
              || await caches.match('/offline.html');
        }
      })()
    );
    return;
  }

  // ASSETS: Cache First validado
  event.respondWith(
    (async () => {
      const cached = await caches.match(request);
      if (cached) return cached;
      try {
        const res = await fetch(request);
        if (res.ok && res.type === 'basic') {
          const cache = await caches.open(CACHES.runtime);
          cache.put(request, res.clone());
          trimCache(CACHES.runtime, MAX_RUNTIME_ENTRIES);
        }
        return res;
      } catch {
        return new Response('', { status: 504, statusText: 'Offline' });
      }
    })()
  );
});

